230	
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner != null) {
237	            Pet pet = owner.getPet(petId);
238	            if (pet != null) {
239	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
240	            }
241	        }
242	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
243	    }
244	
245	    /**
246	     * Builds the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
247	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN}
248	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners.
249	     * For example an owner named "Smithers" created when 10 owners already exist gets {@code 'SMI-0011'}.
250	     *
251	     * @param lastName the owner's last name
252	     * @return the assigned customer code
253	     */
254	    /**
255	     * Counts how many existing owners share the given first and last name, compared
256	     * case-insensitively, at the moment before the new owner is persisted. The result is
257	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
258	     * stood when the owner was created rather than being recomputed on later reads.
259	     *
260	     * @param firstName the first name of the owner being created
261	     * @param lastName the last name of the owner being created
262	     * @return the number of pre-existing owners with the same first and last name
263	     */
264	    private int countNamesakes(String firstName, String lastName) {
265	        String first = firstName == null ? "" : firstName;
266	        String last = lastName == null ? "" : lastName;
267	        return (int) this.clinicService.findAllOwners().stream()
268	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
269	                && last.equalsIgnoreCase(existing.getLastName()))
270	            .count();
271	    }
272	
273	    private String nextCustomerCode(String lastName) {
274	        String letters = lastName == null ? "" : lastName;
275	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
276	        int sequence = this.clinicService.findAllOwners().size() + 1;
277	        return String.format("%s-%04d", last3, sequence);
278	    }
279	
280	    /**
281	     * Rejects an owner payload that is missing or blank in any of the required fields
282	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
283	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
284	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
285	     * guard enforces the rule uniformly for every required field.
286	     *
287	     * @param ownerFieldsDto the submitted owner payload
288	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
289	     */
290	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
291	        List<String> invalidFields = new ArrayList<>();
292	        if (isBlank(ownerFieldsDto.getFirstName())) {
293	            invalidFields.add("firstName");
294	        }
295	        if (isBlank(ownerFieldsDto.getLastName())) {
296	            invalidFields.add("lastName");
297	        }
298	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
299	            invalidFields.add("address");
300	        }
301	        if (isBlank(ownerFieldsDto.getCity())) {
302	            invalidFields.add("city");
303	        }
304	        if (isBlank(ownerFieldsDto.getTelephone())) {
305	            invalidFields.add("telephone");
306	        }
307	        if (!invalidFields.isEmpty()) {
308	            throw new InvalidOwnerFieldsException(invalidFields);
309	        }
310	    }
311	
312	    private boolean isBlank(String value) {
313	        return value == null || value.isBlank();
314	    }
315	
316	    /**
317	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
318	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
319	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
320	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
321	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
322	     *
323	     * @param telephone the raw telephone value from the submitted owner payload
324	     * @return the normalized E.164 telephone number
325	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
326	     */
327	    private String normalizeTelephone(String telephone) {
328	        String raw = telephone == null ? "" : telephone.strip();
329	        boolean hasCountryCode = raw.startsWith("+");
330	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
331	        String digits;
332	        if (hasCountryCode) {
333	            digits = cleaned.substring(1);
334	        } else {
335	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
336	            digits = "61" + national;
337	        }
338	        if (!digits.matches("[0-9]{8,15}")) {
339	            throw new InvalidOwnerFieldsException(List.of("telephone"));
340	        }
341	        return "+" + digits;
342	    }
343	
344	    /**
345	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
346	     * returning {@code null} when the value cannot form a valid E.164 number.
347	     *
348	     * @param telephone an existing owner's stored telephone value
349	     * @return the E.164 form, or {@code null} if it cannot be normalized
350	     */
351	    private String toE164OrNull(String telephone) {
352	        try {
353	            return normalizeTelephone(telephone);
354	        } catch (InvalidOwnerFieldsException ex) {
355	            return null;
356	        }
357	    }
358	
359	    /**
360	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
361	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
362	     * accepted value is trimmed and lower-cased before it is stored and returned.
363	     *
364	     * @param email the raw email value from the submitted owner payload, may be {@code null}
365	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
366	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
367	     */
368	    private String normalizeEmail(String email) {
369	        if (email == null) {
370	            return null;
371	        }
372	        String trimmed = email.strip();
373	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
374	            throw new InvalidOwnerFieldsException(List.of("email"));
375	        }
376	        return trimmed.toLowerCase(Locale.ROOT);
377	    }
378	
379	    /**
380	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
381	     * Existing owners' telephones are converted to E.164 form before comparison so that
382	     * differently-formatted representations of the same number are treated as duplicates.
383	     *
384	     * @param normalizedTelephone the E.164 telephone of the owner being created
385	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
386	     */
387	    private void rejectDuplicateTelephone(String normalizedTelephone) {
388	        boolean duplicate = this.clinicService.findAllOwners().stream()
389	            .map(Owner::getTelephone)
390	            .filter(telephone -> telephone != null)
391	            .map(this::toE164OrNull)
392	            .filter(telephone -> telephone != null)
393	            .anyMatch(normalizedTelephone::equals);
394	        if (duplicate) {
395	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
396	        }
397	    }
398	
399	    /**
400	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
401	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
402	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
403	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
404	     *
405	     * @param lastName the last name of the owner being created
406	     * @param address the address of the owner being created
407	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
408	     */
409	    private void rejectDuplicateHousehold(String lastName, String address) {
410	        String normalizedLastName = normalizeForComparison(lastName);
411	        String normalizedAddress = normalizeAddress(address);
412	        boolean duplicate = this.clinicService.findAllOwners().stream()
413	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
414	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
415	        if (duplicate) {
416	            throw new DuplicateOwnerHouseholdException(lastName, address);
417	        }
418	    }
419	
420	    /**
421	     * Assigns the owner being created a household identifier when the request opts into sharing a
422	     * household. The identifier is a stable value derived from the owner's normalized last name and
423	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
424	     * value regardless of creation order. Any already-existing owner in the same household that has no
425	     * identifier yet is back-filled with the same value so the whole household stays consistent.
426	     *
427	     * @param owner the owner being created, whose household id is set in place
428	     */
429	    private void assignHousehold(Owner owner) {
430	        String householdId = householdId(owner.getLastName(), owner.getAddress());
431	        String normalizedLastName = normalizeForComparison(owner.getLastName());
432	        String normalizedAddress = normalizeAddress(owner.getAddress());
433	        for (Owner existing : this.clinicService.findAllOwners()) {
434	            if (existing.getHouseholdId() == null
435	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
436	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
437	                existing.setHouseholdId(householdId);
438	                this.clinicService.saveOwner(existing);
439	            }
440	        }
441	        owner.setHouseholdId(householdId);
442	    }
443	
444	    /**
445	     * Derives the stable household identifier for a given last name and address. The value is
446	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
447	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
448	     * the same household therefore always produce the same identifier.
449	     *
450	     * @param lastName the owner's last name
451	     * @param address the owner's address
452	     * @return the stable household identifier
453	     */
454	    private String householdId(String lastName, String address) {
455	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
456	        try {
457	            byte[] digest = MessageDigest.getInstance("SHA-256")
458	                .digest(key.getBytes(StandardCharsets.UTF_8));
459	            StringBuilder hex = new StringBuilder();
460	            for (int i = 0; i < 6; i++) {
461	                hex.append(String.format("%02X", digest[i]));
462	            }
463	            return "HH-" + hex;
464	        } catch (NoSuchAlgorithmException ex) {
465	            throw new IllegalStateException("SHA-256 not available", ex);
466	        }
467	    }
468	
469	    /**
470	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
471	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
472	     * result is lower-cased. A {@code null} value normalizes to the empty string.
473	     *
474	     * @param value the value to normalize, may be {@code null}
475	     * @return the normalized value
476	     */
477	    private String normalizeForComparison(String value) {
478	        if (value == null) {
479	            return "";
480	        }
481	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
482	    }
483	
484	    /**
485	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
486	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
487	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
488	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
489	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
490	     * that is stored, returned, and used for every address comparison (household duplicate detection
491	     * and the shared household id).
492	     *
493	     * @param address the raw address value from the submitted owner payload, may be {@code null}
494	     * @return the normalized address
495	     */
496	    private String normalizeAddress(String address) {
497	        if (address == null) {
498	            return "";
499	        }
500	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
501	        if (collapsed.isEmpty()) {
502	            return "";
503	        }
504	        String[] tokens = collapsed.split(" ");
505	        StringBuilder normalized = new StringBuilder();
506	        for (int i = 0; i < tokens.length; i++) {
507	            if (i > 0) {
508	                normalized.append(' ');
509	            }
510	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
511	        }
512	        return normalized.toString();
513	    }
514	}
